mapper.insert:
INSERT INTO contract (
contract_no, contract_date, contract_duration, each_payment, basic_pay_with,
payment_term, payment_day, insured_name, insured_ssn, other_matters, product_no,
customer_no, employee_no, last_reform_date, last_inseminatee
)
VALUES (
#{contractNo}, #{contractDate}, #{contractDuration}, #{eachPayment}, #{basicPayWith},
#{paymentTerm}, #{paymentDay}, #{insuredName}, #{insuredSsn}, #{otherMatters}, #{productNo},
#{customerNo}, #{employeeNo}, #{lastReformDate}, #{lastInseminatee}
)

mapper.select:
SELECT c.customer_name AS contractName, ct.insured_name AS insuredName, p.product_name AS productName, ct.contract_date AS contractDate, CASE WHEN p.product_category = 1 THEN '메리츠화재' WHEN p.product_category = 2 THEN '현대해상' WHEN p.product_category = 3 THEN '한화손해보험' WHEN p.product_category = 4 THEN '삼성화재' WHEN p.product_category = 5 THEN 'DB손해보험' WHEN p.product_category = 31 THEN 'MetLife' WHEN p.product_category = 32 THEN '한화생명' WHEN p.product_category = 33 THEN 'SinhanLife' WHEN p.product_category = 34 THEN '흥국생명' WHEN p.product_category = 35 THEN '라이나생명' ELSE '기타' END AS insuranceCompany, ct.contract_no AS contractNo, d.department_name AS departmentName, e.employee_name AS employeeName, ct.employee_no AS employeeNo FROM contract ct INNER JOIN customer c ON ct.customer_no = c.customer_no INNER JOIN productmanage p ON p.product_no = ct.product_no INNER JOIN employee e ON ct.employee_no = e.employee_no INNER JOIN department d ON e.department_no = d.department_no WHERE 1=1
AND c.customer_name LIKE CONCAT('%', #{customerName}, '%')
AND ct.insured_name LIKE CONCAT('%', #{insuredName}, '%')
AND c.customer_ssn = #{customerSsn}
AND ct.insured_ssn = #{insuredSsn}
AND e.employee_no = #{employeeNo}
AND e.employee_name LIKE CONCAT('%', #{employeeName}, '%')
AND MONTH(ct.contractDate) = #{month}
